import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
params={'db':'pubmed','term':'ritonavir fluticasone beclomethasone Cushing syndrome management','retmode':'json','retmax':8}
r=requests.get(u,params=params,timeout=20)
print('HTTP',r.status_code)
ids=r.json()['esearchresult']['idlist']
print('PMIDs',ids)
if ids:
 s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i,s[i].get('title'),s[i].get('pubdate'))
